CREATE TABLE communication_settings(id integer PRIMARY KEY CHECK(id=1),data jsonb NOT NULL,password_encrypted text,version integer NOT NULL DEFAULT 1,verified_version integer,updated_by uuid NOT NULL REFERENCES public.users(id));
CREATE TABLE outgoing_messages(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),document_id uuid NOT NULL REFERENCES document_archives(document_id),recipient text NOT NULL,subject text NOT NULL,body text NOT NULL,sender text NOT NULL DEFAULT '',sender_name text NOT NULL DEFAULT '',smtp_version integer,version integer NOT NULL DEFAULT 1,status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','queued','sending','sent','failed','uncertain','cancelled')),attempts integer NOT NULL DEFAULT 0,lease_at timestamptz,error text,created_by uuid NOT NULL REFERENCES public.users(id),created_at timestamptz NOT NULL DEFAULT now(),sent_at timestamptz);
CREATE INDEX outgoing_work ON outgoing_messages(created_at) WHERE status IN ('queued','sending');
ALTER TABLE outgoing_messages ADD COLUMN queued_by uuid REFERENCES public.users(id);
CREATE TABLE message_attempts(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,message_id uuid NOT NULL REFERENCES outgoing_messages(id),attempt integer NOT NULL,state text NOT NULL,details jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
CREATE TRIGGER immutable_message_attempts BEFORE UPDATE OR DELETE ON message_attempts FOR EACH ROW EXECUTE FUNCTION guard_immutable();
CREATE FUNCTION guard_message_content() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.document_id<>OLD.document_id OR NEW.created_by<>OLD.created_by OR (OLD.status NOT IN ('draft','failed','cancelled') AND (NEW.recipient,NEW.subject,NEW.body,NEW.sender,NEW.sender_name) IS DISTINCT FROM (OLD.recipient,OLD.subject,OLD.body,OLD.sender,OLD.sender_name)) THEN RAISE EXCEPTION 'El mensaje enviado o en curso conserva su contenido original'; END IF; RETURN NEW; END $$;
CREATE TRIGGER message_content BEFORE UPDATE ON outgoing_messages FOR EACH ROW EXECUTE FUNCTION guard_message_content();
CREATE TABLE portal_shares(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),document_id uuid NOT NULL REFERENCES document_archives(document_id),token_hash text NOT NULL UNIQUE,token_encrypted text NOT NULL,recipient text NOT NULL,allow_sign boolean NOT NULL DEFAULT false,file_ids uuid[] NOT NULL DEFAULT '{}',expires_at timestamptz NOT NULL,revoked_at timestamptz,created_by uuid NOT NULL REFERENCES public.users(id),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE portal_receipts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),share_id uuid NOT NULL UNIQUE REFERENCES portal_shares(id),document_id uuid NOT NULL REFERENCES documents(id),sha256 text NOT NULL,decision text NOT NULL CHECK(decision IN ('accept','reject')),signer_name text NOT NULL,declaration text NOT NULL,ip text NOT NULL,user_agent text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TRIGGER immutable_portal_receipts BEFORE UPDATE OR DELETE ON portal_receipts FOR EACH ROW EXECUTE FUNCTION guard_immutable();
CREATE TABLE portal_events(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,share_id uuid NOT NULL REFERENCES portal_shares(id),event text NOT NULL CHECK(event IN ('view','pdf','attachment')),created_at timestamptz NOT NULL DEFAULT now());
CREATE TRIGGER immutable_portal_events BEFORE UPDATE OR DELETE ON portal_events FOR EACH ROW EXECUTE FUNCTION guard_immutable();
